typedef struct { void (*action)(Ctx *); State next; } Row;
static const Row table[N_STATES][N_SIGNALS] = {
    [SELECT]  = { [CHOSEN] = { pick_account, AMOUNT } },
    [AMOUNT]  = { [NEXT]   = { validate_amount, CONFIRM },
                  [BACK]   = { NULL,          SELECT  } },
};
void flow_dispatch(Ctx *c, Signal sig) {
    const Row *r = &table[c->state][sig];
    if (r->action) r->action(c);
    c->state = r->next;
}
